<?php
require_once __DIR__ . '/includes/functions.php';
require_once __DIR__ . '/includes/timetable_store.php';
header('Content-Type: application/json; charset=utf-8');
$user=cds_user();if(!$user){http_response_code(401);echo json_encode(['ok'=>false,'message'=>'Chưa đăng nhập.'],JSON_UNESCAPED_UNICODE);exit;}
if(!hash_equals((string)($_SESSION['tkb_range_csrf']??''),(string)($_POST['csrf']??''))){http_response_code(403);echo json_encode(['ok'=>false,'message'=>'Phiên làm việc không hợp lệ.'],JSON_UNESCAPED_UNICODE);exit;}
$isAdmin=(($user['role']??'')==='admin');$canApprove=$isAdmin||cds_can_feature('cm.pccm','edit');
$teachers=array_values(array_filter(array_map('strval',(array)load_json(TEACHERS_FILE,[]))));$selfTeacher=trim((string)($user['teacher_name']??$user['name']??''));if($selfTeacher!==''&&!in_array($selfTeacher,$teachers,true))foreach($teachers as$t)if(tkb_key($t)===tkb_key($selfTeacher)){$selfTeacher=$t;break;}
$date=trim((string)($_POST['date']??''));$week=tkb_week_by_id(trim((string)($_POST['week_id']??'')));$slotKey=trim((string)($_POST['slot_key']??''));$sub=trim((string)($_POST['substitute_teacher']??''));$absent=trim((string)($_POST['absent_teacher']??''));if(!$canApprove&&$selfTeacher!=='')$absent=$selfTeacher;
if(!$week||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$slotKey===''||$sub===''||$absent===''){echo json_encode(['ok'=>false,'message'=>'Thiếu dữ liệu đăng ký dạy thay.'],JSON_UNESCAPED_UNICODE);exit;}
$target=null;foreach(tkb_resolved_slots($week)as$slot)if(tkb_slot_key($slot)===$slotKey&&($slot['teacher']??'')===$absent){$target=$slot;break;}if(!$target){echo json_encode(['ok'=>false,'message'=>'Không tìm thấy tiết cần dạy thay.'],JSON_UNESCAPED_UNICODE);exit;}
