$fit=tkb_teacher_fit($sub,$target,$week,$date);$status=$canApprove?'approved':'pending';$className=(string)($target['class']?:$target['class_raw']);$row=['date'=>$date,'start_date'=>$date,'end_date'=>$date,'week_id'=>$week['id'],'slot_key'=>$slotKey,'day'=>(int)$target['day'],'session'=>(string)$target['session'],'period'=>(int)$target['period'],'class'=>$className,'class_raw'=>(string)($target['class_raw']??''),'subject'=>(string)$target['subject'],'absent_teacher'=>$absent,'substitute_teacher'=>$sub,'assigned_to'=>$sub,'fit_labels'=>$fit['labels'],'status'=>$status,'kind'=>'task','title'=>'Dạy thay '.(string)$target['subject'].' lớp '.$className.' · '.$sub,'url'=>BASE_URL.'thoikhoabieu.php?tab=substitution&date='.rawurlencode($date),'active'=>false,'publish_dashboard'=>false,'requested_at'=>date('c'),'requested_by'=>(string)($user['name']??$selfTeacher),'updated_at'=>date('c'),'updated_by'=>(string)($user['name']??'')];if($status==='approved'){$row['approved_at']=date('c');$row['approved_by']=(string)($user['name']??'');}
if(!tkb_save_substitution($row)){http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Không lưu được lịch dạy thay.'],JSON_UNESCAPED_UNICODE);exit;}
echo json_encode(['ok'=>true,'status'=>$status,'message'=>$status==='approved'?'Đã xác nhận lịch dạy thay.':'Đã gửi đăng ký, chờ Tổ trưởng chuyên môn hoặc Quản trị duyệt.'],JSON_UNESCAPED_UNICODE);
